// 有 bug 的 reducer：default 分支返回新对象 -> 未知 action 也触发重渲染
function badReducer(state, action) {
  switch (action.type) {
    case 'ADD':
      return { ...state, todos: [...state.todos, action.todo] };
    default:
      return { ...state };          // BUG：引用变了，订阅者被无谓通知
  }
}
// 修复：未知 action 原样返回旧引用，让「引用剪枝」生效
function goodReducer(state, action) {
  switch (action.type) {
    case 'ADD':
      return { ...state, todos: [...state.todos, action.todo] };
    default:
      return state;                 // FIX
  }
}

const base = { todos: [] };
function countNotifies(reducer) {
  let state = base;
  let notify = 0;
  for (let i = 0; i < 3; i++) {
    const next = reducer(state, { type: 'NOOP' });
    if (next !== state) notify += 1;
    state = next;
  }
  return notify;
}
console.log('buggy_notifies=' + countNotifies(badReducer));
console.log('fixed_notifies=' + countNotifies(goodReducer));

# TTL + stale-while-revalidate：用整数逻辑时钟给出 fresh/stale/expired 状态序列
def create_cache(ttl_ms, swr_ms):
    store = {}
    clock = {'now': 0}

    def advance(ms):
        clock['now'] += ms

    def write(key, value):
        store[key] = {'value': value, 'at': clock['now']}

    def read(key):
        e = store.get(key)
        if e is None:
            return {'value': None, 'state': 'miss'}
        age = clock['now'] - e['at']
        if age <= ttl_ms:
            return {'value': e['value'], 'state': 'fresh'}
        if age <= ttl_ms + swr_ms:
            return {'value': e['value'], 'state': 'stale'}     # 先给旧值，后台刷新
        return {'value': None, 'state': 'expired'}

    return {'advance': advance, 'write': write, 'read': read}


c = create_cache(100, 200)
print('t0=%s' % c['read']('k')['state'])
c['write']('k', 'v1')
print('after_write=%s' % c['read']('k')['state'])
c['advance'](110)
