c['advance'](200)
print('t310=%s value=%s' % (c['read']('k')['state'], c['read']('k')['value']))

// 请求调度：优先级队列 + 最大并发限制（峰值并发不超限，完成即补位）
function createScheduler(maxConcurrent) {
  const waiting = [];
  const active = [];
  let seq = 0;
  let peak = 0;
  function admit() {
    while (active.length < maxConcurrent && waiting.length) {
      waiting.sort((a, b) => (b.priority - a.priority) || (a.seq - b.seq));
      active.push(waiting.shift());
    }
    peak = Math.max(peak, active.length);
  }
  return {
    enqueue(id, priority) { waiting.push({ id, priority, seq: seq++ }); return this; },
    admit,
    completeOne() {
      if (active.length === 0) return null;
      const job = active.shift();
      admit();                 // 完成一个立刻补位，保持并发打满
      return job.id;
    },
    get peak() { return peak; },
    get active() { return active.length; },
    get waiting() { return waiting.length; },
  };
}

const s = createScheduler(3);
for (const [id, p] of [['a', 1], ['b', 5], ['c', 3], ['d', 5], ['e', 2], ['f', 4], ['g', 1]]) {
  s.enqueue(id, p);
}
s.admit();
console.log('peak=' + s.peak + ' active=' + s.active + ' waiting=' + s.waiting);
const order = [];
while (s.waiting > 0 || s.active > 0) {
  const id = s.completeOne();
  if (id === null) break;
  order.push(id);
}
console.log('order=' + order.join(','));
console.log('peak_within_limit=' + (s.peak <= 3));
console.log('all_done=' + (order.length === 7));

// 二分下界：返回第一个 >= target 的下标；越界返回数组长度
// 参考实现见 trekhleb/javascript-algorithms 的二分查找章节（本题仅存元数据与链接）
function lowerBound(nums, target) {
  let lo = 0;
  let hi = nums.length;
  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (nums[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}
const nums = [10, 20, 20, 30, 40];
console.log('lb_20=' + lowerBound(nums, 20));
console.log('lb_25=' + lowerBound(nums, 25));
console.log('lb_41=' + lowerBound(nums, 41));
console.log('lb_5=' + lowerBound(nums, 5));

// LRU 缓存（哈希表 + 双向链表）：get/put 均 O(1)
// 与本章「服务端状态缓存」同构：容量满时淘汰最久未使用项
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map();          // key -> node
    this.head = { key: null, val: null, prev: null, next: null };
    this.tail = { key: null, val: null, prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }
  _remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }
  _pushFront(node) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next.prev = node;
    this.head.next = node;
  }
  get(key) {
    if (!this.map.has(key)) return -1;
    const node = this.map.get(key);
    this._remove(node);
    this._pushFront(node);         // 命中即移到最前（最近使用）
    return node.val;
  }
  put(key, val) {
    if (this.map.has(key)) {
      const node = this.map.get(key);
      node.val = val;
      this._remove(node);
      this._pushFront(node);
      return;
    }
    if (this.map.size >= this.capacity) {
      const lru = this.tail.prev;  // 链表尾部 = 最久未使用
      this._remove(lru);
      this.map.delete(lru.key);
    }
    const node = { key, val, prev: null, next: null };
    this._pushFront(node);
    this.map.set(key, node);
  }
}

const c = new LRUCache(2);
c.put(1, 1);
c.put(2, 2);
